.next/server/chunks/ssr/[root-of-the-server]__1r9qycb._.js.map:1:{"version":3,"sources":["../../../../app/page.tsx","../../../../app/RevenueChart.tsx","../../../../app/LatestInvoices.tsx","../../../../app/CardStats.tsx","../../../../node_modules/next/src/server/route-modules/app-page/module.compiled.js"],"sourcesContent":["import { cache, Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

const getDashboardData = cache(async (): Promise<DashboardData> => {
  const response = await fetch('https://api.example.com/dashboard')

  if (!response.ok) {
    throw new Error('Failed to load dashboard data')
  }

  return response.json()
})

async function CardStatsData() {
  const data = await getDashboardData()

  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartData() {
  const { revenue } = await getDashboardData()

  return <RevenueChart revenue={revenue} />
}

async function LatestInvoicesData() {
  const { invoices } = await getDashboardData()

  return <LatestInvoices invoices={invoices} />
}

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-busy="true">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>Loading...</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>Loading...</p>
      </div>
    </div>
  )
}

function RevenueChartSkeleton() {
  return (
    <div className="chart" aria-busy="true">
      <h2>Revenue</h2>
      <p>Loading chart...</p>
    </div>
  )
}

function LatestInvoicesSkeleton() {
  return (
    <div className="invoices" aria-busy="true">
      <h2>Latest Invoices</h2>
      <p>Loading invoices...</p>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsData />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartData />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesData />
      </Suspense>
    </main>
  )
}
","export function RevenueChart({
  revenue,
}: {
  revenue: { month: string; amount: number }[]
}) {
  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}
","export function LatestInvoices({
  invoices,
}: {
  invoices: { id: string; name: string; amount: number }[]
}) {
  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}
","export function CardStats({
  totalRevenue,
  totalInvoices,
}: {
  totalRevenue: number
  totalInvoices: number
}) {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}
